import { ACCESS_DENIED_MESSAGE, corsHeaders } from '../_shared/hub-core.ts';
import { exchangeAccessCode } from '../_shared/hub-service.ts';
import { SupabaseHubRepository } from '../_shared/supabase-repository.ts';
import { adminClient, cryptoPort } from '../_shared/runtime.ts';

function json(origin: string, status: number, body: Record<string, unknown>) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders(origin), 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
}

Deno.serve(async request => {
  const origin = request.headers.get('origin') || '';
  const cors = corsHeaders(origin);
  if (request.method === 'OPTIONS') return new Response('ok', { status: cors['Access-Control-Allow-Origin'] ? 200 : 403, headers: cors });
  if (request.method !== 'POST' || !cors['Access-Control-Allow-Origin']) return json(origin, 403, { error: ACCESS_DENIED_MESSAGE });

  try {
    const body = await request.json();
    const repository = new SupabaseHubRepository(adminClient());
    const result = await exchangeAccessCode({
      code: body?.code,
      view: body?.view,
      repository,
      cryptoPort,
    });
    return json(origin, 200, result);
  } catch (error) {
    if (error instanceof Error && error.message === ACCESS_DENIED_MESSAGE) return json(origin, 401, { error: ACCESS_DENIED_MESSAGE });
    console.error('verify-hub-access failed', error);
    return json(origin, 500, { error: 'The Performance Hub is temporarily unavailable.' });
  }
});

export const ACCESS_DENIED_MESSAGE = 'Access code not recognized. Please contact Coach Du.';
export const PROGRAMME_PENDING_MESSAGE = 'Programme week is being prepared.';
export const SESSION_EXPIRED_MESSAGE = 'Your Hub session has expired. Enter your access code again.';

const PRODUCTION_ORIGINS = new Set([
  'https://duairlineseliteacademy.com',
  'https://www.duairlineseliteacademy.com',
  'https://hiktwkdfvlujszczthdu.supabase.co',
]);

const PROTOTYPE_ORIGINS = new Set([
  'http://terminal.local:4173',
  'https://du-airlines-performance-hub-pilot.light-auk-1409.chatgpt.site',
  'https://du-airlines-performance-hub-pilot.duchenge28.chatgpt.site',
]);

export function corsHeaders(origin = ''): Record<string, string> {
  const local = /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin);
  const headers: Record<string, string> = {
    'Access-Control-Allow-Headers': 'authorization,apikey,content-type,x-du-session',
    'Access-Control-Allow-Methods': 'POST,OPTIONS',
    'Vary': 'Origin',
  };
  if (PRODUCTION_ORIGINS.has(origin) || PROTOTYPE_ORIGINS.has(origin) || local) {
    headers['Access-Control-Allow-Origin'] = origin;
  }
  return headers;
}

export function normalizeCode(value: unknown): string {
  return typeof value === 'string' ? value.trim().toLowerCase() : '';
}

export function validateLoginInput(input: { code?: unknown; view?: unknown }): { code: string; view: 'athlete' | 'staff' } {
  const code = normalizeCode(input?.code);
  const view = input?.view;
  if (code.length < 12 || code.length > 128 || (view !== 'athlete' && view !== 'staff')) {
    throw new Error(ACCESS_DENIED_MESSAGE);
  }
  return { code, view };
}

export function codeTypeForView(view: 'athlete' | 'staff'): 'cohort' | 'staff' {
  return view === 'staff' ? 'staff' : 'cohort';
}

export function isCodeUsable(record: any, view: 'athlete' | 'staff', now = new Date()): boolean {
  if (!record || record.status !== 'active' || !record.cohort_id) return false;
  if (record.code_type !== codeTypeForView(view)) return false;
  if (record.expires_at && new Date(record.expires_at).getTime() <= now.getTime()) return false;
  return true;
}

export function isSessionUsable(record: any, now = new Date()): boolean {
  if (!record || !record.cohort_id || record.revoked_at) return false;
  if (!record.expires_at || new Date(record.expires_at).getTime() <= now.getTime()) return false;
  return record.role === 'athlete' || record.role === 'staff';
}

export function prepareBundleForDelivery(bundle: any) {
  if (!bundle?.cohort || !bundle?.programme) return null;
  const published = bundle?.week
    && (bundle.week.status === 'live' || bundle.week.status === 'completed')
    && bundle.week.verification_status === 'verified'
    && bundle.week.published_at;
  if (published) return bundle;
  return { ...bundle, week: null, trainingDays: [], blocks: [], exercises: [] };
}

function unique<T>(values: T[]): T[] {
  return [...new Set(values)];
}

function firstText(blocks: any[], key: string): string {
  for (const block of blocks) {
    const value = block?.content?.[key];
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}

function prescriptionsFrom(blocks: any[]) {
  return blocks.flatMap(block => Array.isArray(block?.content?.prescriptions)
    ? block.content.prescriptions
        .filter((item: any) => typeof item?.exerciseCode === 'string' && item.exerciseCode.trim())
        .map((item: any) => ({
          exerciseCode: item.exerciseCode.trim(),
          dosage: typeof item.dosage === 'string' ? item.dosage : '',
          rest: typeof item.rest === 'string' ? item.rest : '',
          cues: typeof item.cues === 'string' ? item.cues : '',
          equipment: typeof item.equipment === 'string' ? item.equipment : '',
          alternativeExerciseCode: typeof item.alternativeExerciseCode === 'string' ? item.alternativeExerciseCode : '',
          ...(typeof item.originalExerciseCode === 'string' && item.originalExerciseCode
            ? { originalExerciseCode: item.originalExerciseCode } : {}),
          ...(typeof item.substitutionNote === 'string' && item.substitutionNote
            ? { substitutionNote: item.substitutionNote } : {}),
        }))
    : []);
}

function routinePlaylistsFrom(blocks: any[]) {
  return blocks.flatMap(block => Array.isArray(block?.content?.playlists) ? block.content.playlists : [])
    .filter((item: any) => {
      const id = typeof item?.id === 'string' && /^[A-Za-z0-9_-]{6,100}$/.test(item.id.trim());
      const url = typeof item?.url === 'string' && /^https:\/\/(www\.|m\.)?youtube\.com\/playlist\?[^\s]*\blist=[A-Za-z0-9_-]{6,100}(?:&[^\s]*)?$/i.test(item.url.trim());
      return id || url;
    })
    .map((item: any) => ({
      type: typeof item.type === 'string' && item.type.trim() ? item.type.trim() : 'routine',
      title: typeof item.title === 'string' && item.title.trim() ? item.title.trim() : 'Session Playlist',
      id: typeof item.id === 'string' && /^[A-Za-z0-9_-]{6,100}$/.test(item.id.trim()) ? item.id.trim() : '',
      url: typeof item.url === 'string' ? item.url.trim() : '',
    }));
}

export function shapeBootstrap(input: {
  role: 'athlete' | 'staff';
  cohort: any;
  programme: any;
  week: any;
  trainingDays: any[];
  blocks: any[];
  exercises: any[];
  personalNote?: string;
}) {
  const { role, cohort, programme, week } = input;
  const cohortPayload = {
    id: cohort.id,
    name: cohort.name,
    currentWeek: cohort.current_week,
    startDate: cohort.start_date || '',
  };
  if (!week) {
    const expectedSessions = Number.isInteger(cohort.expected_sessions_per_week)
      ? Math.min(7, Math.max(1, cohort.expected_sessions_per_week)) : 3;
    return {
      contentStatus: 'preparing',
      role,
      cohort: cohortPayload,
      programme: {
        id: programme.id,
        school: cohort.name,
        title: programme.name,
        sport: programme.sport || '',
        week: cohort.current_week,
        totalWeeks: programme.duration_weeks,
        weeklyObjective: 'Your programme week is being prepared.',
        athleteEducation: '',
        programmeNotes: '',
        coachGuidance: '',
        sessions: Array.from({ length: expectedSessions }, (_, index) => ({
          id: `preparing-day-${index + 1}`,
          day: `Day ${index + 1}`,
          title: 'Session being prepared',
          duration: '',
          objective: 'Coach Du will publish this session before your programme begins.',
          prescriptions: [],
          playlist: { id: '', url: '' },
          locked: true,
        })),
      },
      exercises: [],
    };
  }
  const trainingDays = [...(input.trainingDays || [])].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
  const allBlocks = input.blocks || [];

  const sessions = trainingDays.map((day, index) => {
    const blocks = allBlocks
      .filter(block => block.training_day_id === day.id)
      .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
    const items = blocks.flatMap(block => Array.isArray(block?.content?.items) ? block.content.items.filter((item: unknown) => typeof item === 'string') : []);
    const exerciseCodes = unique(blocks.flatMap(block => Array.isArray(block?.content?.exerciseCodes) ? block.content.exerciseCodes.filter((code: unknown) => typeof code === 'string') : []));
    const athleteNotes = blocks.map(block => block.athlete_note).filter((note: unknown) => typeof note === 'string' && note.trim());
    const staffNotes = blocks.map(block => block.staff_note).filter((note: unknown) => typeof note === 'string' && note.trim());
    const prescriptions = prescriptionsFrom(blocks);
    const session: Record<string, unknown> = {
      id: day.id,
      day: day.day_key || `Day ${index + 1}`,
      requirement: firstText(blocks, 'requirement') || 'Mandatory',
      title: day.title || `Day ${index + 1}`,
      duration: day.duration || '',
      focus: firstText(blocks, 'focus') || day.intensity || day.objective || '',
      objective: day.objective || '',
      why: firstText(blocks, 'why'),
      watch: firstText(blocks, 'watch'),
      items,
      exerciseCodes,
      playlist: {
        id: day.playlist_id || '',
        url: day.playlist_url || '',
      },
      playlists: routinePlaylistsFrom(blocks),
      prescriptions,
      athleteNote: athleteNotes.join('\n'),
    };
    if (role === 'staff') session.staffNote = staffNotes.join('\n');
    return session;
  });

  const referencedCodes = new Set(allBlocks.flatMap(block => {
    const legacyCodes = Array.isArray(block?.content?.exerciseCodes) ? block.content.exerciseCodes : [];
    const prescriptionCodes = prescriptionsFrom([block]).flatMap(item => [item.exerciseCode, item.alternativeExerciseCode]);
    return [...legacyCodes, ...prescriptionCodes].filter(code => typeof code === 'string' && code.trim());
  }));
  const exercises = (input.exercises || []).filter(exercise => referencedCodes.has(exercise.code)).map(exercise => ({
    id: exercise.id,
    code: exercise.code,
    title: exercise.name,
    category: exercise.categories || (exercise.category_slug ? [exercise.category_slug] : []),
    videoId: exercise.video_id || '',
    videoUrl: exercise.video_url || '',
    description: exercise.description || '',
    purpose: exercise.purpose || '',
    coachingCues: exercise.coaching_cues || '',
    defaultDosage: exercise.default_dosage || '',
    order: exercise.display_order || 0,
    active: true,
  }));
  const staffGuidance = unique(allBlocks
    .map(block => block.staff_note)
    .filter((note: unknown) => typeof note === 'string' && note.trim()))
    .join(' ');
  const programmeNotes = [
    week.running_focus ? `Running: ${week.running_focus}` : '',
    week.strength_focus ? `Strength: ${week.strength_focus}` : '',
    week.event_focus ? `Event: ${week.event_focus}` : '',
  ].filter(Boolean).join(' • ');

  return {
    contentStatus: 'published',
    role,
    cohort: cohortPayload,
    programme: {
      id: programme.id,
      school: cohort.name,
      title: programme.name,
      sport: programme.sport || '',
      week: week.week_number,
      totalWeeks: programme.duration_weeks,
      weeklyObjective: week.weekly_objective || '',
      athleteEducation: week.athlete_education || '',
      programmeNotes: role === 'staff' ? programmeNotes : '',
      coachGuidance: role === 'staff' ? staffGuidance : '',
      personalNote: typeof input.personalNote === 'string' ? input.personalNote : '',
      sessions,
    },
    exercises,
  };
}

import {
  ACCESS_DENIED_MESSAGE,
  PROGRAMME_PENDING_MESSAGE,
  SESSION_EXPIRED_MESSAGE,
  isCodeUsable,
  isSessionUsable,
  prepareBundleForDelivery,
  shapeBootstrap,
  validateLoginInput,
} from './hub-core.ts';

export async function exchangeAccessCode({ code, view, now = new Date(), repository, cryptoPort }: any) {
  let input;
  try {
    input = validateLoginInput({ code, view });
  } catch {
    throw new Error(ACCESS_DENIED_MESSAGE);
  }
  const codeHash = await cryptoPort.sha256(input.code);
  const record = await repository.findAccessCode(codeHash);
  if (!isCodeUsable(record, input.view, now)) throw new Error(ACCESS_DENIED_MESSAGE);
  const cohort = await repository.findCohort(record.cohort_id);
  if (!cohort || cohort.status !== 'live') throw new Error(ACCESS_DENIED_MESSAGE);

  const rawToken = cryptoPort.randomToken();
  const tokenHash = await cryptoPort.sha256(rawToken);
  const expiresAt = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString();
  await repository.createSession({
    token_hash: tokenHash,
    role: input.view,
    cohort_id: record.cohort_id,
    access_code_id: record.id,
    expires_at: expiresAt,
  });
  await repository.touchCode(record.id, now.toISOString());
  return { token: rawToken, role: input.view, expiresAt };
}

export async function bootstrapHub({ token, now = new Date(), repository, cryptoPort }: any) {
  if (typeof token !== 'string' || token.length < 16 || token.length > 256) throw new Error(SESSION_EXPIRED_MESSAGE);
  const tokenHash = await cryptoPort.sha256(token);
  const session = await repository.findSession(tokenHash);
  if (!isSessionUsable(session, now)) throw new Error(SESSION_EXPIRED_MESSAGE);
  const accessCode = await repository.findAccessCodeById(session.access_code_id);
  if (!isCodeUsable(accessCode, session.role, now) || accessCode.cohort_id !== session.cohort_id) {
    throw new Error(SESSION_EXPIRED_MESSAGE);
  }
  const cohort = await repository.findCohort(session.cohort_id);
  if (!cohort || cohort.status !== 'live') throw new Error(SESSION_EXPIRED_MESSAGE);

  const bundle = prepareBundleForDelivery(await repository.loadCurrentProgramme(session.cohort_id));
  if (!bundle) {
    throw new Error(PROGRAMME_PENDING_MESSAGE);
  }
  await repository.touchSession(session.id, now.toISOString());
  return shapeBootstrap({ role: session.role, ...bundle });
}

type SupabaseClient = any;

const PROFESSIONAL_MEMBER_FIELDS = [
  'id', 'user_id', 'first_name', 'last_name', 'email', 'member_type', 'founding_member',
  'membership_price', 'membership_status', 'paid', 'primary_goals', 'work_environment',
  'training_environment', 'preferred_duration', 'current_frequency', 'equipment',
  'training_experience', 'limitations', 'onboarding_complete', 'selected_plan',
  'selected_plan_label', 'selected_plan_price', 'cohort_id', 'access_status',
  'access_reason', 'payment_status', 'programme_start_date',
  'coach_note', 'exercise_substitutions',
].join(',');

const PARENT_ATHLETE_FIELDS = [
  'id', 'parent_user_id', 'athlete_user_id', 'athlete_email', 'parent_first_name', 'parent_last_name', 'parent_email',
  'full_name', 'display_name', 'cohort_id', 'access_status', 'paid',
  'access_reason', 'payment_status', 'programme_start_date',
  'coach_note', 'exercise_substitutions',
  'onboarding_complete', 'onboarding_data',
].join(',');

function assertResult<T>(result: { data: T; error: any }, operation: string): T {
  if (result.error) throw new Error(`${operation}: ${result.error.message}`);
  return result.data;
}

export class SupabaseHubRepository {
  private client: SupabaseClient;

  constructor(client: SupabaseClient) {
    this.client = client;
  }

  async findProfessionalMember(userId: string) {
    return assertResult(
      await this.client.from('professional_members')
        .select(PROFESSIONAL_MEMBER_FIELDS)
        .eq('user_id', userId)
        .maybeSingle(),
      'Professional member lookup failed',
    );
  }

  async ensureProfessionalMember(user: { id: string; email?: string; user_metadata?: any }) {
    const existing = await this.findProfessionalMember(user.id);
    if (existing) return existing;
    const payload = {
      user_id: user.id,
      first_name: typeof user.user_metadata?.first_name === 'string' ? user.user_metadata.first_name.trim() : '',
      last_name: typeof user.user_metadata?.last_name === 'string' ? user.user_metadata.last_name.trim() : '',
      email: user.email || '',
      member_type: 'professional',
      founding_member: true,
    };
    return assertResult(
      await this.client.from('professional_members')
        .insert(payload)
        .select(PROFESSIONAL_MEMBER_FIELDS)
        .single(),
      'Professional member creation failed',
    );
  }

  async updateProfessionalOnboarding(userId: string, safeFields: Record<string, unknown>) {
    return assertResult(
      await this.client.from('professional_members')
        .update(safeFields)
        .eq('user_id', userId)
        .select(PROFESSIONAL_MEMBER_FIELDS)
        .single(),
      'Professional onboarding update failed',
    );
  }

  async findParentAthlete(userId: string) {
    return assertResult(
      await this.client.from('athletes')
        .select(PARENT_ATHLETE_FIELDS)
        .eq('parent_user_id', userId)
        .maybeSingle(),
      'Parent athlete lookup failed',
    );
  }

  async ensureParentAthlete(user: { id: string; email?: string; user_metadata?: any }) {
    const existing = await this.findParentAthlete(user.id);
    if (existing) return existing;
    const athleteFirst = typeof user.user_metadata?.athlete_first_name === 'string'
      ? user.user_metadata.athlete_first_name.trim() : '';
    const athleteLast = typeof user.user_metadata?.athlete_last_name === 'string'
      ? user.user_metadata.athlete_last_name.trim() : '';
    const payload = {
      parent_user_id: user.id,
      parent_first_name: typeof user.user_metadata?.first_name === 'string' ? user.user_metadata.first_name.trim() : '',
      parent_last_name: typeof user.user_metadata?.last_name === 'string' ? user.user_metadata.last_name.trim() : '',
      parent_email: user.email || '',
      full_name: [athleteFirst, athleteLast].filter(Boolean).join(' '),
      display_name: athleteFirst,
      access_status: 'pending',
    };
    return assertResult(
      await this.client.from('athletes')
        .insert(payload)
        .select(PARENT_ATHLETE_FIELDS)
        .single(),
      'Parent athlete creation failed',
    );
  }

  async updateParentOnboarding(userId: string, safeFields: Record<string, unknown>) {
    return assertResult(
      await this.client.from('athletes')
        .update(safeFields)
        .eq('parent_user_id', userId)
        .select(PARENT_ATHLETE_FIELDS)
        .single(),
      'Parent onboarding update failed',
    );
  }

  async findPrivateAthlete(userId: string) {
    return assertResult(
      await this.client.from('athletes')
        .select(PARENT_ATHLETE_FIELDS)
        .eq('athlete_user_id', userId)
        .maybeSingle(),
      'Private athlete lookup failed',
    );
  }

  async ensurePrivateAthlete(user: { id: string; email?: string; user_metadata?: any }) {
    const existing = await this.findPrivateAthlete(user.id);
    if (existing) return existing;
    const firstName = typeof user.user_metadata?.first_name === 'string' ? user.user_metadata.first_name.trim() : '';
    const lastName = typeof user.user_metadata?.last_name === 'string' ? user.user_metadata.last_name.trim() : '';
    return assertResult(
      await this.client.from('athletes')
        .insert({
          athlete_user_id: user.id,
          athlete_email: user.email || '',
          full_name: [firstName, lastName].filter(Boolean).join(' '),
          display_name: firstName,
          access_status: 'pending',
        })
        .select(PARENT_ATHLETE_FIELDS)
        .single(),
      'Private athlete creation failed',
    );
  }

  async updatePrivateAthleteOnboarding(userId: string, safeFields: Record<string, unknown>) {
    return assertResult(
      await this.client.from('athletes')
        .update(safeFields)
        .eq('athlete_user_id', userId)
        .select(PARENT_ATHLETE_FIELDS)
        .single(),
      'Private athlete onboarding update failed',
    );
  }

  async findAccessCode(codeHash: string) {
    return assertResult(
      await this.client.from('access_codes')
        .select('id,status,code_type,cohort_id,expires_at')
        .eq('code_hash', codeHash)
        .eq('status', 'active')
        .maybeSingle(),
      'Access lookup failed',
    );
  }

  async createSession(row: Record<string, unknown>) {
    assertResult(await this.client.from('hub_sessions').insert(row), 'Session creation failed');
  }

  async findAccessCodeById(id: string) {
    return assertResult(
      await this.client.from('access_codes')
        .select('id,status,code_type,cohort_id,expires_at')
        .eq('id', id)
        .maybeSingle(),
      'Access status lookup failed',
    );
  }

  async touchCode(id: string, at: string) {
    assertResult(await this.client.from('access_codes').update({ last_used_at: at }).eq('id', id), 'Code update failed');
  }

  async findSession(tokenHash: string) {
    return assertResult(
      await this.client.from('hub_sessions')
        .select('id,role,cohort_id,access_code_id,revoked_at,expires_at')
        .eq('token_hash', tokenHash)
        .maybeSingle(),
      'Session lookup failed',
    );
  }

  async touchSession(id: string, at: string) {
    assertResult(await this.client.from('hub_sessions').update({ last_active_at: at }).eq('id', id), 'Session update failed');
  }

  async findCohort(id: string) {
    return assertResult(
      await this.client.from('cohorts')
        .select('id,status')
        .eq('id', id)
        .maybeSingle(),
      'Cohort status lookup failed',
    );
  }

  async loadCurrentProgramme(cohortId: string) {
    const cohort = assertResult(
      await this.client.from('cohorts')
        .select('id,name,current_week,status,programme_id,tier,start_date,expected_sessions_per_week')
        .eq('id', cohortId)
        .eq('status', 'live')
        .maybeSingle(),
      'Cohort lookup failed',
    );
    if (!cohort?.programme_id) return null;

    const programme = assertResult(
      await this.client.from('programmes')
        .select('id,name,duration_weeks,sport')
        .eq('id', cohort.programme_id)
        .maybeSingle(),
      'Programme lookup failed',
    );
    if (!programme) return null;

    let weekQuery = this.client.from('programme_weeks')
        .select('id,programme_id,week_number,phase,weekly_objective,running_focus,strength_focus,event_focus,athlete_education,status,verification_status,published_at')
        .eq('programme_id', programme.id)
        .eq('week_number', cohort.current_week)
        .in('status', ['live', 'completed'])
        .eq('verification_status', 'verified')
        .not('published_at', 'is', null);
    if (cohort.tier) {
      const tier = assertResult(
        await this.client.from('programme_tiers')
          .select('id')
          .eq('programme_id', programme.id)
          .eq('name', cohort.tier)
          .maybeSingle(),
        'Programme tier lookup failed',
      );
      if (!tier) return { cohort, programme, week: null, trainingDays: [], blocks: [], exercises: [] };
      weekQuery = weekQuery.eq('tier_id', tier.id);
    } else {
      weekQuery = weekQuery.is('tier_id', null);
    }
    const week = assertResult(
      await weekQuery.maybeSingle(),
      'Programme week lookup failed',
    );
    if (!week) return { cohort, programme, week: null, trainingDays: [], blocks: [], exercises: [] };

    const trainingDays = assertResult(
      await this.client.from('training_days')
        .select('id,programme_week_id,day_key,title,intensity,objective,duration,sort_order,playlist_id,playlist_url')
        .eq('programme_week_id', week.id)
        .order('sort_order'),
      'Training days lookup failed',
    ) || [];
    const dayIds = trainingDays.map((day: any) => day.id);
    const blocks = dayIds.length ? (assertResult(
      await this.client.from('session_blocks')
        .select('id,training_day_id,block_type,title,sort_order,content,athlete_note,staff_note')
        .in('training_day_id', dayIds)
        .order('sort_order'),
      'Session blocks lookup failed',
    ) || []) : [];
    const referencedCodes = [...new Set(blocks.flatMap((block: any) => {
      const legacyCodes = Array.isArray(block?.content?.exerciseCodes) ? block.content.exerciseCodes : [];
      const prescriptions = Array.isArray(block?.content?.prescriptions) ? block.content.prescriptions : [];
      const prescriptionCodes = prescriptions.flatMap((item: any) => [item?.exerciseCode, item?.alternativeExerciseCode]);
      return [...legacyCodes, ...prescriptionCodes]
        .filter((code: unknown) => typeof code === 'string' && code.trim())
        .map((code: string) => code.trim());
    }))];
    const exercises = referencedCodes.length ? (assertResult(
      await this.client.from('exercises')
        .select('id,code,name,category_slug,categories,video_id,video_url,description,purpose,coaching_cues,default_dosage,display_order,active')
        .in('code', referencedCodes)
        .eq('active', true)
        .order('display_order'),
      'Exercise lookup failed',
    ) || []) : [];

    return { cohort, programme, week, trainingDays, blocks, exercises };
  }

  async loadExercisesByCodes(codes: string[]) {
    if (!codes.length) return [];
    return assertResult(
      await this.client.from('exercises')
        .select('id,code,name,category_slug,categories,video_id,video_url,description,purpose,coaching_cues,default_dosage,display_order,active')
        .in('code', codes)
        .eq('active', true)
        .order('display_order'),
      'Replacement exercise lookup failed',
    ) || [];
  }
}

import { createClient } from 'npm:@supabase/supabase-js@2.95.0';

export function adminClient() {
  const url = Deno.env.get('SUPABASE_URL');
  let key = '';
  const newKeys = Deno.env.get('SUPABASE_SECRET_KEYS');
  if (newKeys) {
    try { key = JSON.parse(newKeys).default || ''; } catch { key = ''; }
  }
  key ||= Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
  if (!url || !key) throw new Error('Supabase function environment is incomplete.');
  return createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } });
}

export async function verifiedUserFromRequest(request: Request) {
  const authorization = request.headers.get('authorization') || '';
  const match = authorization.match(/^Bearer\s+([^\s]+)$/i);
  if (!match) return null;
  const token = match[1];
  const { data, error } = await adminClient().auth.getUser(token);
  if (error || !data?.user) return null;
  return data.user;
}

export const cryptoPort = {
  async sha256(value: string) {
    const bytes = new TextEncoder().encode(value);
    const digest = await crypto.subtle.digest('SHA-256', bytes);
    return [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('');
  },
  randomToken() {
    const bytes = new Uint8Array(32);
    crypto.getRandomValues(bytes);
    return [...bytes].map(byte => byte.toString(16).padStart(2, '0')).join('');
  },
};
